// -----------------------------------------------------------------------------
// <auto-generated>
//     This file contains the bootstrap logic for the TomatoNovel API.
//     It configures middleware, OpenAPI documentation, EF Core, OpenIddict
//     authentication/authorization, dependency injection and global services.
